    // [seed arx]
    std::uint8_t *aSource = pWorkSpace->mSource;
    READ_IN_MUTABLE_PARAMS;
    [[maybe_unused]] const std::uint64_t aNonceWordA = TwistMix64::DiffuseC(pNonce * 0x84D81A5A9B621809ULL + 0xBF6C5C93755BDDF7ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordB = TwistMix64::DiffuseC(pNonce * 0xEC5BA89476CAA35DULL + 0xA1AB69CC5F51616AULL);
