            aOrbiterE = (aWandererE + RotL64(aScatter, 35U)) + 0xCB0E4463414A8B56ULL;
            aOrbiterK = (((aWandererH + RotL64(aIngress, 5U)) + RotL64(aCarry, 53U)) + 0x5AE5D49D9F3A6AA4ULL) + aTwistOrbiterAssignSaltA[(((31U - aIndex) + 17U)) & S_SALT1];
            aOrbiterA = (aWandererD + RotL64(aScatter, 19U)) + 0xB5CFE9F5073B1461ULL;
            aOrbiterJ = (((aWandererC + RotL64(aCross, 13U)) + RotL64(aCarry, 37U)) + 0xDAD8F33716185103ULL) + aTwistOrbiterAssignSaltD[((aIndex + 25U)) & S_SALT1];
