            aOrbiterD = (aWandererG + RotL64(aPrevious, 29U)) + 0x1FDCE624465F2C70ULL;
            aOrbiterI = (aWandererJ + RotL64(aCross, 21U)) + 0x3A13763CAEFC4381ULL;
            aOrbiterF = (aWandererB + RotL64(aIngress, 37U)) + 0xD81E643306AFE602ULL;
            aOrbiterC = (aWandererI + RotL64(aScatter, 23U)) + 0x9CF576554C23D2E7ULL;
            //
            aOrbiterB = (aOrbiterB + aOrbiterH) + 0x42F611EBABF0E362ULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterB) ^ 0x83D503EA7AB0D2D7ULL;
            aOrbiterE = RotL64((aOrbiterE * 0xC8F7F797A18E8095ULL), 39U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterK) + 0x0515A711D54E680CULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterE) ^ 0xF0265869F9D03C7AULL;
            aOrbiterA = RotL64((aOrbiterA * 0xE44427BEB9B4A675ULL), 41U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterB) + 0x98CFE238AB90A44EULL;
            aOrbiterG = ((aOrbiterG ^ aOrbiterJ) ^ 0xD269F8EE0B10713CULL) ^ aTwistOrbiterUpdateSaltE[(((31U - aIndex) + 14U)) & S_SALT1];
            aOrbiterG = RotL64((aOrbiterG * 0xD776BC1F7708FCA3ULL), 19U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterE) + 0x9E89075A60ECD10CULL;
            aOrbiterD = ((aOrbiterD ^ aOrbiterG) ^ 0xEA96EA9CB0A486FCULL) ^ aTwistOrbiterUpdateSaltD[((aIndex + 7U)) & S_SALT1];
            aOrbiterD = RotL64((aOrbiterD * 0x7AEB28BD7E110FC1ULL), 3U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterF) + 0xCF66D92A14E1FB64ULL;
            aOrbiterB = ((aOrbiterB ^ aOrbiterI) ^ 0xCD2F219294E2DCA1ULL) ^ aTwistOrbiterUpdateSaltC[(((31U - aIndex) + 29U)) & S_SALT1];
            aOrbiterB = RotL64((aOrbiterB * 0xFCCBF4A07C972049ULL), 11U);
            //
            aOrbiterA = ((aOrbiterA + aOrbiterC) + 0xD03DC377C4B15F93ULL) + aTwistOrbiterUpdateSaltB[((aIndex + 11U)) & S_SALT1];
