            //
            aOrbiterA = (((aWandererC + RotL64(aScatter, 42U)) + RotL64(aCarry, 13U)) + 0xDEF469D6687ABA77ULL) + aTwistOrbiterAssignSaltD[(((31U - aIndex) + 28U)) & S_SALT1];
            aOrbiterI = ((aWandererI + RotL64(aIngress, 5U)) + RotL64(aCarry, 39U)) + 0xBD238C229010F832ULL;
