            //
            aIngress = (RotL64(aWoodLaneA[((aIndex + 2118U)) & S_BLOCK1], 27U) ^ RotL64(aWoodLaneB[((aIndex + 403U)) & S_BLOCK1], 54U));
            aIngress ^= (RotL64(aSoilLaneC[((aIndex + 1498U)) & S_BLOCK1], 19U) ^ RotL64(aHeartLaneD[((aIndex + 1518U)) & S_BLOCK1], 43U));
