            aCross = (RotL64(aWoodLaneC[((S_BLOCK1 - aIndex + 1552U)) & S_BLOCK1], 34U) ^ RotL64(aWoodLaneD[((S_BLOCK1 - aIndex + 3314U)) & S_BLOCK1], 57U));
