            //
            aOrbiterB = ((aWandererC + RotL64(aScatter, 51U)) + RotL64(aCarry, 23U)) + 0x1A971638C9177211ULL;
            aOrbiterI = (aWandererG + RotL64(aPrevious, 29U)) + 0x8EF47EA306D99E31ULL;
            aOrbiterJ = (aWandererH + RotL64(aCross, 13U)) + 0xF29A912C62130112ULL;
            aOrbiterA = (((aWandererF + RotL64(aIngress, 23U)) + RotL64(aCarry, 53U)) + 0x896D1DAA3F65E648ULL) + aTwistOrbiterAssignSaltA[(((31U - aIndex) + 18U)) & S_SALT1];
            aOrbiterD = (aWandererK + RotL64(aCross, 60U)) + 0x64519C744B577155ULL;
            aOrbiterH = ((aWandererJ + RotL64(aPrevious, 3U)) + RotL64(aCarry, 11U)) + 0xABCF3AAEB4A2F0A0ULL;
