            aIngress ^= (RotL64(aIceLaneD[((aIndex + 9929U)) & S_BLOCK1], 58U) ^ RotL64(aMagmaLaneA[((S_BLOCK1 - aIndex + 14888U)) & S_BLOCK1], 3U));
            aIngress = TwistMix64::DiffuseC((aIngress ^ aKeyRotateADomainWordIngress));
