            aOrbiterC = (aWandererH + RotL64(aIngress, 54U)) + 0xAB26A9E90119BAD1ULL;
            aOrbiterH = (((aWandererK + RotL64(aScatter, 39U)) + RotL64(aCarry, 23U)) + 0x928563C7D1210723ULL) + aKeyRotateAOrbiterAssignSaltD[((aIndex + 22U)) & S_SALT1];
