            aOrbiterD = (((aWandererB + RotL64(aPrevious, 5U)) + RotL64(aCarry, 13U)) + 0x1E0B3D34DBA039A1ULL) + aKeyRotateAOrbiterAssignSaltE[((aIndex + 17U)) & S_SALT1];
