            aOrbiterK = RotL64((aOrbiterK * 0x6AA6D1B9F81D2CADULL), 35U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterK) + 0xA336EE555519C70BULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterB) ^ 0x07BC3274F529A301ULL;
