            //
            aScatter = (RotL64(aCross, 41U) ^ RotL64(aPrevious, 57U)) ^ (RotL64(aIngress, 14U) + RotL64(aCarry, 27U));
            aScatter = TwistMix64::DiffuseC((aScatter ^ aKeyRotateADomainWordScatter));
            //
            aOrbiterB = (aWandererG + RotL64(aPrevious, 54U)) + 0x8C8574715C04FB45ULL;
            aOrbiterD = (((aWandererI + RotL64(aIngress, 3U)) + RotL64(aCarry, 29U)) + 0x7E1C08B7711D80F2ULL) + aKeyRotateAOrbiterAssignSaltE[((aIndex + 4U)) & S_SALT1];
            aOrbiterH = ((aWandererD + RotL64(aScatter, 47U)) + RotL64(aCarry, 43U)) + 0x865827F36EB35C28ULL;
            aOrbiterF = (aWandererF + RotL64(aCross, 29U)) + 0xE4F641F31240BF94ULL;
            aOrbiterK = (aWandererC + RotL64(aIngress, 23U)) + 0x40791AB0EE99A8D6ULL;
            aOrbiterJ = ((aWandererJ + RotL64(aPrevious, 37U)) + 0x3D8D6F4B0DEC993AULL) + aKeyRotateAOrbiterAssignSaltA[(((31U - aIndex) + 26U)) & S_SALT1];
            aOrbiterI = ((aWandererA + RotL64(aCross, 13U)) + RotL64(aCarry, 5U)) + 0xFA89ED4AC23F6DBAULL;
            //
            aOrbiterB = ((aOrbiterB + aOrbiterD) + 0x48728BE7505484EDULL) + aKeyRotateAOrbiterUpdateSaltA[((aIndex + 21U)) & S_SALT1];
