            aCross ^= (RotL64(aKeyRowReadB[(((2047U - aIndex) + 8997U)) & W_KEY1], 19U) ^ RotL64(aShadowLaneB[((aIndex + 16032U)) & S_BLOCK1], 3U));
            aCross = TwistMix64::DiffuseA((aCross ^ aKeyRotateADomainWordCross));
            //
            aScatter = (RotL64(aIngress, 5U) + RotL64(aCross, 22U)) ^ (RotL64(aPrevious, 35U) + RotL64(aCarry, 57U));
            aScatter = TwistMix64::DiffuseB((aScatter ^ aKeyRotateADomainWordScatter));
            //
            aOrbiterK = ((aWandererK + RotL64(aPrevious, 51U)) + 0x4ACED78533EC5926ULL) + aKeyRotateAOrbiterAssignSaltB[(((31U - aIndex) + 11U)) & S_SALT1];
            aOrbiterF = (aWandererB + RotL64(aCross, 29U)) + 0x450E8BCAE8C21897ULL;
            aOrbiterA = (aWandererI + RotL64(aScatter, 3U)) + 0xDAF7D93E2216F284ULL;
            aOrbiterJ = (((aWandererA + RotL64(aIngress, 57U)) + RotL64(aCarry, 53U)) + 0x2C050A079BB4C0FCULL) + aKeyRotateAOrbiterAssignSaltF[(((31U - aIndex) + 29U)) & S_SALT1];
            aOrbiterE = ((aWandererH + RotL64(aCross, 35U)) + RotL64(aCarry, 21U)) + 0xF0EDAB88DC76C1EAULL;
            aOrbiterD = (aWandererE + RotL64(aPrevious, 41U)) + 0x0C5C93658C99012BULL;
            aOrbiterG = ((aWandererJ + RotL64(aScatter, 14U)) + RotL64(aCarry, 5U)) + 0x1BDA0FCE2D39262EULL;
            //
            aOrbiterK = (aOrbiterK + aOrbiterF) + 0x2024127AB64583FAULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterK) ^ 0x75F889FCED794D3CULL;
            aOrbiterA = RotL64((aOrbiterA * 0xEFA5586BD49151F9ULL), 11U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterJ) + 0x8D4522147542E09FULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterA) ^ 0xEEA773390E334751ULL;
            aOrbiterE = RotL64((aOrbiterE * 0x49E422473A4CB8E3ULL), 47U);
            //
            aOrbiterD = ((aOrbiterD + aOrbiterE) + 0x1CC90656273DC2D5ULL) + aKeyRotateAOrbiterUpdateSaltF[((aIndex + 27U)) & S_SALT1];
            aOrbiterF = ((aOrbiterF ^ aOrbiterD) ^ 0x6881240A7EA43713ULL) ^ aKeyRotateAOrbiterUpdateSaltB[((aIndex + 19U)) & S_SALT1];
            aOrbiterF = RotL64((aOrbiterF * 0xD49781AA8CC5852FULL), 19U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterK) + 0x301167056CF7E767ULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterE) ^ 0x5A2F991F43309F1BULL;
            aOrbiterG = RotL64((aOrbiterG * 0x659D0879D3C71949ULL), 37U);
            //
            aOrbiterJ = ((aOrbiterJ + aOrbiterD) + 0x14952BACEEE91CD6ULL) + aKeyRotateAOrbiterUpdateSaltD[((aIndex + 20U)) & S_SALT1];
            aOrbiterK = (aOrbiterK ^ aOrbiterJ) ^ 0xED304EE3D9DA0228ULL;
            aOrbiterK = RotL64((aOrbiterK * 0x8C075D9F8F50C999ULL), 53U);
            //
            aOrbiterF = ((aOrbiterF + aOrbiterG) + 0x6D789F1C25DB3090ULL) + aKeyRotateAOrbiterUpdateSaltC[(((31U - aIndex) + 8U)) & S_SALT1];
            aOrbiterJ = (aOrbiterJ ^ aOrbiterF) ^ 0xA4051F767943CD15ULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0x89C944DD0F9B650FULL), 27U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterA) + 0xDC5BBB84A3757C89ULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterG) ^ 0x3A4838D92B3E3465ULL;
            aOrbiterD = RotL64((aOrbiterD * 0x3B825F8937DC7841ULL), 3U);
            //
            aIngress = RotL64(aOrbiterE, 48U) ^ aOrbiterG;
            aIngress = aIngress + (aOrbiterD ^ RotL64(aOrbiterF, 13U));
            aIngress = aIngress + (RotL64(aOrbiterA, 57U) ^ aOrbiterJ);
            aIngress = aIngress + RotL64(aOrbiterK, 5U);
            aIngress = TwistMix64::DiffuseA((aIngress + aScatter));
            //
            aWandererJ = aWandererJ ^ ((RotL64(aPrevious, 53U) + aOrbiterK) + RotL64(aOrbiterJ, 43U));
            aWandererK = aWandererK + (((RotL64(aCross, 4U) + RotL64(aOrbiterA, 21U)) + aOrbiterG) + RotL64(aCarry, 21U));
            aWandererA = aWandererA ^ (((RotL64(aScatter, 39U) + aOrbiterF) + RotL64(aOrbiterG, 6U)) + aKeyRotateAWandererUpdateSaltF[((aIndex + 24U)) & S_SALT1]);
            aWandererE = aWandererE + ((((RotL64(aIngress, 11U) + aOrbiterG) + RotL64(aOrbiterD, 29U)) + RotL64(aCarry, 51U)) + aKeyRotateAWandererUpdateSaltB[(((31U - aIndex) + 26U)) & S_SALT1]);
            aWandererB = aWandererB ^ ((RotL64(aCross, 47U) + RotL64(aOrbiterA, 57U)) + aOrbiterJ);
            aWandererI = aWandererI + ((RotL64(aPrevious, 21U) + RotL64(aOrbiterE, 35U)) + aOrbiterD);
            aWandererH = aWandererH ^ ((RotL64(aIngress, 29U) + RotL64(aOrbiterD, 13U)) + aOrbiterF);
            //
            aCarry = aCarry + (aWandererI ^ RotL64(aWandererJ, 43U));
            aCarry = aCarry + (RotL64(aWandererK, 24U) ^ aWandererE);
            aCarry = aCarry + (RotL64(aWandererH, 35U) ^ aWandererB);
            aCarry = aCarry + RotL64(aWandererA, 29U);
            aCarry = aCarry + RotL64(aIngress, 53U);
            aCarry = TwistMix64::DiffuseA(aCarry);
            //
            aFuseLaneB[S_BLOCK1 - aIndex] = aIngress;
