            aIngress = (RotL64(aFuseLaneB[((aIndex + 16902U)) & S_BLOCK1], 37U) ^ RotL64(aWindLaneD[((aIndex + 18634U)) & S_BLOCK1], 5U));
            aIngress ^= (RotL64(aSoilLaneB[((aIndex + 18530U)) & S_BLOCK1], 58U) ^ RotL64(aHeartLaneC[((S_BLOCK1 - aIndex + 19026U)) & S_BLOCK1], 21U));
            aIngress = TwistMix64::DiffuseC((aIngress ^ aKeyRotateADomainWordIngress));
            //
            aCross = (RotL64(aFuseLaneA[((S_BLOCK1 - aIndex + 23093U)) & S_BLOCK1], 26U) ^ RotL64(aWindLaneB[((S_BLOCK1 - aIndex + 24460U)) & S_BLOCK1], 3U));
            aCross ^= (RotL64(aIceLaneA[((S_BLOCK1 - aIndex + 19510U)) & S_BLOCK1], 53U) ^ RotL64(aShadowLaneA[((S_BLOCK1 - aIndex + 21972U)) & S_BLOCK1], 11U));
            aCross = TwistMix64::DiffuseC((aCross ^ aKeyRotateADomainWordCross));
            //
            aScatter = (RotL64(aPrevious, 11U) ^ RotL64(aCross, 23U)) + (RotL64(aCarry, 44U) ^ RotL64(aIngress, 57U));
            aScatter = TwistMix64::DiffuseC((aScatter ^ aKeyRotateADomainWordScatter));
            //
            aOrbiterJ = (aWandererB + RotL64(aIngress, 57U)) + 0xC0E6969E464A5B59ULL;
            aOrbiterG = ((aWandererJ + RotL64(aCross, 19U)) + RotL64(aCarry, 27U)) + 0x0673C705DA6853BDULL;
            aOrbiterH = ((aWandererI + RotL64(aScatter, 34U)) + RotL64(aCarry, 5U)) + 0x9442FB5A98678BAEULL;
            aOrbiterC = ((aWandererE + RotL64(aPrevious, 5U)) + 0xFB0333BD07BB0C6CULL) + aKeyRotateAOrbiterAssignSaltD[(((31U - aIndex) + 29U)) & S_SALT1];
            aOrbiterB = (((aWandererH + RotL64(aIngress, 41U)) + RotL64(aCarry, 41U)) + 0x95D02325C7889DE1ULL) + aKeyRotateAOrbiterAssignSaltC[(((31U - aIndex) + 14U)) & S_SALT1];
            aOrbiterF = (aWandererD + RotL64(aScatter, 51U)) + 0x4854F8DF0D0FECE1ULL;
            aOrbiterD = (aWandererA + RotL64(aPrevious, 13U)) + 0x72BE5A7F27766083ULL;
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterG) + 0x2EA784B1DAC06293ULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterJ) ^ 0x9042A8CE43CAB3D4ULL;
            aOrbiterH = RotL64((aOrbiterH * 0x32DF4D51585C122BULL), 41U);
            //
            aOrbiterG = ((aOrbiterG + aOrbiterH) + 0x2BF2C390337AB2E9ULL) + aKeyRotateAOrbiterUpdateSaltA[((aIndex + 12U)) & S_SALT1];
            aOrbiterC = (aOrbiterC ^ aOrbiterG) ^ 0xBA33D5EB10475AA9ULL;
            aOrbiterC = RotL64((aOrbiterC * 0xFA823EDF83BAAFA3ULL), 51U);
            //
            aOrbiterB = ((aOrbiterB + aOrbiterF) + 0xF042ACC089AD36F8ULL) + aKeyRotateAOrbiterUpdateSaltE[((aIndex + 23U)) & S_SALT1];
            aOrbiterJ = (aOrbiterJ ^ aOrbiterB) ^ 0x7DE51D6B6992A286ULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0xD19F08D1D06BB233ULL), 35U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterD) + 0xACE0E6EED648BF9DULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterC) ^ 0x018ECED5DB645719ULL;
            aOrbiterB = RotL64((aOrbiterB * 0xA85C477D05C3B297ULL), 3U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterB) + 0x50229DEE8E9ABB60ULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterD) ^ 0x528085D8A6321665ULL;
            aOrbiterF = RotL64((aOrbiterF * 0x120C35278602ED9BULL), 13U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterJ) + 0x5949C32EFC6E3246ULL;
            aOrbiterG = ((aOrbiterG ^ aOrbiterF) ^ 0x22F4DF4E6F770B1EULL) ^ aKeyRotateAOrbiterUpdateSaltC[((aIndex + 5U)) & S_SALT1];
            aOrbiterG = RotL64((aOrbiterG * 0x3DEBE0F8248C72BDULL), 21U);
            //
            aOrbiterH = ((aOrbiterH + aOrbiterC) + 0x715E607DC4B92A25ULL) + aKeyRotateAOrbiterUpdateSaltD[(((31U - aIndex) + 17U)) & S_SALT1];
            aOrbiterD = (aOrbiterD ^ aOrbiterH) ^ 0x890E5398F6F0E669ULL;
            aOrbiterD = RotL64((aOrbiterD * 0x17E33DA430F0A8E3ULL), 29U);
            //
            aIngress = aOrbiterB ^ RotL64(aOrbiterJ, 3U);
            aIngress = aIngress + (aOrbiterH ^ RotL64(aOrbiterF, 35U));
            aIngress = aIngress + (RotL64(aOrbiterG, 57U) ^ aOrbiterC);
            aIngress = aIngress + RotL64(aOrbiterD, 27U);
            aIngress = TwistMix64::DiffuseC((aIngress + aScatter));
            //
            aWandererA = aWandererA + (((RotL64(aScatter, 39U) + aOrbiterH) + RotL64(aOrbiterJ, 57U)) + aKeyRotateAWandererUpdateSaltD[((aIndex + 9U)) & S_SALT1]);
            aWandererB = aWandererB ^ ((RotL64(aPrevious, 29U) + RotL64(aOrbiterB, 50U)) + aOrbiterJ);
            aWandererD = aWandererD + ((RotL64(aIngress, 11U) + aOrbiterC) + RotL64(aOrbiterD, 11U));
            aWandererH = aWandererH ^ ((RotL64(aCross, 20U) + aOrbiterC) + RotL64(aOrbiterG, 41U));
            aWandererJ = aWandererJ + ((((RotL64(aScatter, 3U) + RotL64(aOrbiterF, 21U)) + aOrbiterB) + RotL64(aCarry, 51U)) + aKeyRotateAWandererUpdateSaltE[(((31U - aIndex) + 25U)) & S_SALT1]);
            aWandererE = aWandererE ^ ((RotL64(aIngress, 53U) + RotL64(aOrbiterH, 29U)) + aOrbiterC);
