            //
            aOrbiterI = ((aWandererE + RotL64(aCross, 35U)) + RotL64(aCarry, 37U)) + 0x1F962DBF0341D62AULL;
            aOrbiterG = ((aWandererG + RotL64(aScatter, 21U)) + RotL64(aCarry, 53U)) + 0x596BEF459BBD0549ULL;
            aOrbiterE = ((aWandererH + RotL64(aPrevious, 5U)) + RotL64(aCarry, 19U)) + 0xCDB198DDC6810730ULL;
            aOrbiterH = ((aWandererA + RotL64(aIngress, 60U)) + 0x59DAD7C7A93EF863ULL) + aKeyRotateBOrbiterAssignSaltC[((aIndex + 11U)) & S_SALT1];
            aOrbiterA = (aWandererB + RotL64(aScatter, 43U)) + 0xD7B264D968C2CF4FULL;
            aOrbiterK = (aWandererD + RotL64(aIngress, 13U)) + 0xF817BBF6D4435FCBULL;
            aOrbiterC = ((aWandererF + RotL64(aPrevious, 27U)) + 0x6F89BE43598452D5ULL) + aKeyRotateBOrbiterAssignSaltF[((aIndex + 15U)) & S_SALT1];
